/** Archived issues are never overdue — an archived issue has no due date. */
const LIVE_ONLY = {} as const;

const logger = createLogger("overdue-issue-job");

/**
 * Issues announced and still overdue on the previous sweep. A later sweep
 * stays quiet while the issue keeps coming back overdue. The moment a sweep
 * does not find it (closed, archived, deleted workspace, or not yet due),
 * it leaves this set, and the next sweep that finds it overdue announces
 * it again.
 */
const reported = new Set<string>();

